import json
import asyncio
from playwright.async_api import async_playwright

# Load data
with open('/app/benchmark/source_data.json') as f:
    data = json.load(f)

sankey_data = data['energy_sankey']
nodes = {n['id']: n for n in sankey_data['nodes']}
flows = sankey_data['flows']

# Node categories and colors
node_colors = {
    # Fossil fuels - dark grays/charcoals
    'oil': '#2d2d2d',
    'coal': '#4a4a4a',
    'natural_gas': '#6e6e6e',
    # Nuclear - muted blue-purple
    'nuclear': '#5b4b8a',
    # Renewables - greens and teals
    'hydro': '#0d7377',
    'wind': '#14919b',
    'solar': '#34a853',
    'biomass': '#6b8e23',
    'geothermal': '#8fbc8f',
    # Transformation - slate blues
    'thermal_power': '#3d5a80',
    'refining': '#4a6fa5',
    'direct_use': '#557a95',
    'electricity_grid': '#6b8cae',
    # End use - warm muted tones
    'transport': '#b85c38',
    'industry': '#c4733e',
    'buildings': '#d4915d',
    'agriculture': '#d9a566',
    'other': '#deb887',
    # Waste heat - vivid red/orange to stand out
    'waste_heat': '#e74c3c',
}

# Build nodes list preserving order from data
node_list = sankey_data['nodes']
node_ids = [n['id'] for n in node_list]
node_index = {nid: i for i, nid in enumerate(node_ids)}

# Prepare links for D3
links = []
for f in flows:
    links.append({
        'source': node_index[f['source']],
        'target': node_index[f['target']],
        'value': f['value']
    })

# Create node data for D3
node_data = []
for n in node_list:
    node_data.append({
        'name': n['label'],
        'id': n['id'],
        'color': node_colors.get(n['id'], '#999')
    })

# Build HTML with D3 Sankey
html_content = f'''<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Global Energy Flow 2022</title>
<script src="https://d3js.org/d3.v7.min.js"></script>
<script src="https://unpkg.com/d3-sankey@0.12.3/dist/d3-sankey.min.js"></script>
<style>
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    background: #f7f5f2;
    font-family: 'IBM Plex Sans', 'Segoe UI', system-ui, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 40px 20px;
    min-height: 100vh;
  }}
  .title {{
    font-family: 'IBM Plex Sans', sans-serif;
    font-size: 28px;
    font-weight: 600;
    color: #1a1a2e;
    margin-bottom: 8px;
    text-align: center;
    letter-spacing: -0.02em;
  }}
  .subtitle {{
    font-size: 14px;
    color: #5a5a6e;
    margin-bottom: 30px;
    text-align: center;
    font-weight: 400;
  }}
  #chart {{
    background: #ffffff;
    border-radius: 8px;
    box-shadow: 0 2px 12px rgba(0,0,0,0.06);
    padding: 20px;
  }}
  .node-label {{
    font-family: 'IBM Plex Sans', sans-serif;
    font-size: 11px;
    font-weight: 600;
    fill: #1a1a2e;
    pointer-events: none;
  }}
  .node-label-small {{
    font-family: 'IBM Plex Sans', sans-serif;
    font-size: 10px;
    font-weight: 400;
    fill: #5a5a6e;
    pointer-events: none;
  }}
  .link {{
    fill: none;
    stroke-opacity: 0.45;
    transition: stroke-opacity 0.2s;
  }}
  .link:hover {{
    stroke-opacity: 0.7;
  }}
  .legend {{
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 16px 24px;
    margin-top: 24px;
    max-width: 1100px;
  }}
  .legend-group {{
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 12px;
    color: #4a4a5a;
    font-weight: 500;
  }}
  .legend-dot {{
    width: 10px;
    height: 10px;
    border-radius: 2px;
    flex-shrink: 0;
  }}
  .axis-label {{
    font-family: 'IBM Plex Sans', sans-serif;
    font-size: 13px;
    font-weight: 600;
    fill: #3a3a4e;
    text-anchor: middle;
  }}
  .unit-label {{
    font-family: 'IBM Plex Sans', sans-serif;
    font-size: 11px;
    fill: #7a7a8e;
    text-anchor: middle;
  }}
</style>
</head>
<body>
<div class="title">Global Energy Flow 2022</div>
<div class="subtitle">Primary sources → Transformation processes → End-use sectors | Values in exajoules (EJ)</div>
<div id="chart"></div>
<div class="legend" id="legend"></div>
<script>
const width = 1100;
const height = 680;
const margin = {{top: 50, right: 160, bottom: 30, left: 160}};

const svg = d3.select("#chart")
  .append("svg")
  .attr("width", width)
  .attr("height", height);

const nodeData = {json.dumps(node_data)};
const linkData = {json.dumps(links)};

const sankey = d3.sankey()
  .nodeId(d => d.index)
  .nodeWidth(18)
  .nodePadding(14)
  .extent([[margin.left, margin.top], [width - margin.right, height - margin.bottom]])
  .nodeAlign(d3.sankeyLeft)
  .nodeSort(null);

// Deep copy to avoid mutation issues
const graph = sankey({{
  nodes: nodeData.map((d, i) => ({{...d, index: i}})),
  links: linkData.map(d => ({{...d}}))
}});

// Color links based on source color, with special handling for waste heat
const linkColor = d => {{
  if (d.target.id === 'waste_heat') return '#e74c3c';
  return d.source.color;
}};

// Draw links
const link = svg.append("g")
  .attr("fill", "none")
  .selectAll("path")
  .data(graph.links)
  .join("path")
  .attr("class", "link")
  .attr("d", d3.sankeyLinkHorizontal())
  .attr("stroke", d => linkColor(d))
  .attr("stroke-width", d => Math.max(1, d.width));

// Draw nodes
const node = svg.append("g")
  .selectAll("rect")
  .data(graph.nodes)
  .join("rect")
  .attr("x", d => d.x0)
  .attr("y", d => d.y0)
  .attr("height", d => Math.max(1, d.y1 - d.y0))
  .attr("width", d => d.x1 - d.x0)
  .attr("fill", d => d.color)
  .attr("rx", 2)
  .attr("stroke", "#fff")
  .attr("stroke-width", 0.5);

// Node labels
svg.append("g")
  .selectAll("text")
  .data(graph.nodes)
  .join("text")
  .attr("class", "node-label")
  .attr("x", d => d.x0 < width / 2 ? d.x0 - 8 : d.x1 + 8)
  .attr("y", d => (d.y0 + d.y1) / 2 - 4)
  .attr("text-anchor", d => d.x0 < width / 2 ? "end" : "start")
  .attr("dy", "0.35em")
  .text(d => d.name);

// Node values
svg.append("g")
  .selectAll("text")
  .data(graph.nodes)
  .join("text")
  .attr("class", "node-label-small")
  .attr("x", d => d.x0 < width / 2 ? d.x0 - 8 : d.x1 + 8)
  .attr("y", d => (d.y0 + d.y1) / 2 + 10)
  .attr("text-anchor", d => d.x0 < width / 2 ? "end" : "start")
  .attr("dy", "0.35em")
  .text(d => d.value ? d.value.toFixed(1) + " EJ" : "");

// Stage labels
const stageY = margin.top - 24;
svg.append("text")
  .attr("class", "axis-label")
  .attr("x", margin.left + 9)
  .attr("y", stageY)
  .text("Primary Sources");

svg.append("text")
  .attr("class", "axis-label")
  .attr("x", width / 2)
  .attr("y", stageY)
  .text("Transformation");

svg.append("text")
  .attr("class", "axis-label")
  .attr("x", width - margin.right - 9)
  .attr("y", stageY)
  .text("End Use");

// Unit labels
const unitY = height - 10;
svg.append("text")
  .attr("class", "unit-label")
  .attr("x", margin.left + 9)
  .attr("y", unitY)
  .text("(EJ)");

svg.append("text")
  .attr("class", "unit-label")
  .attr("x", width / 2)
  .attr("y", unitY)
  .text("(EJ)");

svg.append("text")
  .attr("class", "unit-label")
  .attr("x", width - margin.right - 9)
  .attr("y", unitY)
  .text("(EJ)");

// Legend
const legendData = [
  {{label: "Fossil Fuels", color: "#4a4a4a"}},
  {{label: "Nuclear", color: "#5b4b8a"}},
  {{label: "Renewables", color: "#0d7377"}},
  {{label: "Transformation", color: "#4a6fa5"}},
  {{label: "End-Use Sectors", color: "#b85c38"}},
  {{label: "Waste/Rejected Heat", color: "#e74c3c"}},
];

const legend = d3.select("#legend")
  .selectAll("div")
  .data(legendData)
  .join("div")
  .attr("class", "legend-group");

legend.append("div")
  .attr("class", "legend-dot")
  .style("background-color", d => d.color);

legend.append("span")
  .text(d => d.label);
</script>
</body>
</html>
'''

with open('/app/sankey.html', 'w') as f:
    f.write(html_content)

async def render():
    async with async_playwright() as p:
        browser = await p.chromium.launch()
        page = await browser.new_page(viewport={'width': 1200, 'height': 900})
        await page.goto('file:///app/sankey.html')
        await page.wait_for_timeout(2000)
        await page.screenshot(path='/app/output/result.png', full_page=True)
        await browser.close()

asyncio.run(render())
print("Saved to /app/output/result.png")
